def replace_saved(root, *, curvature_weighted=False, geometric_radial=False, edge_budget=6.5,
                  families=None):
    """Opt-in boundary-budget trial on copied dependencies, retaining guards."""
    from .curved_quad_fair_nodes import assign_group
    if families is not None:
        families=frozenset(families)
        if not families or not families<={'ordinary','multi_site'}:
            raise ValueError('Select ordinary and/or multi_site recipe families')
    replacement=build(budgeted_boundary=True,curvature_weighted=curvature_weighted,
                      geometric_radial=geometric_radial,edge_budget=edge_budget);memo={};changed=[]
    def visit(tree,family=None):
        family=tree.get('st_corner_pattern_family',family)
        key=(tree.as_pointer(),family)
        if key in memo:return memo[key]
        selected=families is None or family in families
        if (selected and geometric_radial and tree.name.startswith('Prochitecture Streets / Local corner pattern v1')
                and ' / Continuous band grading v1' in tree.name
                and tree.get('st_corner_radial_map')!='power_or_geometric_v1'):
            raise ValueError('Rebuild this saved corner pattern before enabling geometric radial spacing')
        if selected and tree.name.startswith(('Prochitecture Streets / Continuous local corner band grading v1',
                                              'Prochitecture Streets / Boundary-budgeted local corner band grading v2')):
            result=replacement;changed.append(tree.name)
        else:
            children=[(node.name,visit(node.node_tree,family)) for node in tree.nodes
                      if node.type=='GROUP' and node.node_tree]
            children=[(name,child) for name,child in children if tree.nodes[name].node_tree!=child]
            result=tree.copy() if children else tree
            for name,child in children:assign_group(result.nodes[name],child)
        memo[key]=result;return result
    roots=root if isinstance(root,(list,tuple)) else [root];results=[visit(tree) for tree in roots]
    if not changed:raise ValueError('No continuous corner-band grading groups found')
    return (results if isinstance(root,(list,tuple)) else results[0]),sorted(set(changed))


